$(document).ready(function(){
    
    if($.inArray(info_dash['pg'], ['noticias', 'videos', 'galerias', 'enquetes_opcoes']) !== -1){
        
        $('<div class="pos-secao-form">' +
        
        '<div class="tt-secao-form">' +
            '<h1>Publicar no Facebook</h1>' +
        '</div>' +
        
        '<div class="secao-form">' +
            
            '<div class="item-form form-triplo">' +
                
                '<div class="item-form-escolha">' +
                    
                    '<span>Publicar nas páginas?</span>' +
                    
                    '<input type="checkbox" id="fb_post" name="facebook_post" value="S">' +
                    
                    '<label for="fb_post">' +
                        '<div class="check-esc">' +
                            '<span>Não</span>' +
                            '<span>Sim</span>' +
                        '</div>' +
                    '</label>' +
                    
                '</div>' +
                
            '</div>' +
            
            '<div class="info-secao-form">' +
                '<span>Publica o link da postagem em suas páginas do Facebook.</span>' +
            '</div>' +
            
        '</div>').insertAfter('form .pos-secao-form:last-of-type');
        
    }
    
    if(info_dash['pg'] == 'plugins' && varGetExist('id') == 'S' && info_dash['var_get']['id'] == 5){
        
        $(".facebook-post-btn").on('click', function(){
            
            $('.status-facebook').html('<span class="icons-multi icon-carregando icon-carregando-fb-post"></span>');
            
            $.ajax({
                url: $(this).data('ajax'),
                type: "POST",
                dataType: 'json',
                success: function(data){
                    
                    if(data['erro'] == 0){
                        
                        window.location.assign(data['link']);
                        
                    } else {
                        
                        $('.status-facebook').html('<div class="col-3"> <div class="item-form"> <span class="info-tbl finalizado" style="padding: 10px; color: #000; font-size: 13px; font-weight: 300;">Falha ao direcionar, atualize esta página e tente novamente!</span> </div> </div>');
                        
                    }
                    
                }
                
            });
            
        });
        
    }
    
});